from pathlib import Path
root=Path(__file__).resolve().parent
checks=[]
def check(label,ok): checks.append((label,bool(ok)))
entity=(root/'src/scheduling/weekly-schedule.entity.ts').read_text()
dto=(root/'src/scheduling/dto/weekly-schedule.dto.ts').read_text()
utils=(root/'src/scheduling/weekly-schedule.utils.ts').read_text()
docsvc=(root/'src/scheduling/scheduling.service.ts').read_text()
docctrl=(root/'src/scheduling/scheduling.controller.ts').read_text()
facsvc=(root/'src/facilities/facilities.service.ts').read_text()
facctrl=(root/'src/facilities/facilities.controller.ts').read_text()
app=(root/'src/app.module.ts').read_text(); ds=(root/'src/database/data-source.ts').read_text()
mod=(root/'src/facilities/facilities.module.ts').read_text(); schedmod=(root/'src/scheduling/scheduling.module.ts').read_text()
mg=(root/'src/database/migrations/1732500000000-CreateWeeklySchedulesForDoctorsAndFacilities.ts').read_text()
docs=(root/'docs/phase-v25-weekly-schedules-doctors-and-facilities.md').read_text()
check('one shared weekly schedule entity supports doctors and facilities', all(x in entity for x in ['doctor','facility','weekday','startTime','endTime','breaks','timezone']))
check('schedule DTO validates weekdays and clock values', all(x in dto for x in ['@Min(0)','@Max(6)','@Matches','@ArrayMaxSize']))
check('breaks must be inside working hours and cannot overlap', 'يجب أن تكون الاستراحة داخل وقت الدوام' in utils and 'فترات الاستراحة متداخلة' in utils)
check('overlapping weekly work periods are rejected', 'فترات الدوام في اليوم نفسه متداخلة' in utils)
check('timezone is validated and Baghdad is the default', 'Asia/Baghdad' in utils and 'Intl.DateTimeFormat' in utils)
check('doctor can read and save weekly work schedule', 'myWeeklySchedule' in docsvc and 'saveWeeklySchedule' in docsvc and 'me/weekly-schedule' in docctrl)
check('doctor schedule does not introduce a fixed consultation duration', 'expectedDurationMinutes' not in docsvc and 'لا يوجد' not in docsvc)
check('doctor appointment slots remain manually created', 'createMany' in docsvc and 'ضمن أوقات دوامك الأسبوعية' in docsvc)
check('doctor slots cannot overlap weekly breaks', 'يتعارض مع فترة الاستراحة' in docsvc and 'ensureSlotFitsSchedule(userId,a,b)' in docsvc)
check('doctor slots remain supported when no weekly rules are configured', 'if(!rules.length) return' in docsvc and 'ensureSlotFitsSchedule(userId,x.range[0],x.range[1])' in docsvc)
check('facility schedule is service-specific', 'serviceId' in facsvc and 'facilityId:facility.id' in facsvc)
check('facility schedule can be publicly viewed', 'publicWeeklySchedule' in facsvc and "@Get(':id/weekly-schedule')" in facctrl)
check('facility slot generation is capped at 31 days', '30) throw new BadRequestException' in facsvc)
check('facility slot generation uses each service expected duration', 'service.expectedDurationMinutes' in facsvc and 'ensureFacilitySlotFitsSchedule(facility.id,service.id,startsAt,endsAt)' in facsvc)
check('facility slot generation skips break overlaps', 'blocked=(rule.breaks??[])' in facsvc)
check('facility slot generation skips past and duplicate slots', 'startsAt<=new Date()||keys.has' in facsvc)
check('facility weekly schedule and slot generation are owner-protected', "@Roles(UserRole.OWNER)" in facctrl and 'generateFacilitySlots' in facctrl)
check('weekly schedule entity is registered in application and migration data source', 'WeeklyScheduleRule' in app and 'WeeklyScheduleRule' in ds)
check('weekly schedule repositories are registered in both modules', 'WeeklyScheduleRule' in mod and 'WeeklyScheduleRule' in schedmod)
check('database migration creates recurring rules and constraints', 'CREATE TABLE weekly_schedule_rules' in mg and 'weekday BETWEEN 0 AND 6' in mg and 'breaks jsonb' in mg)
check('V25 documentation explains both doctor and facility workflows', '## Doctors' in docs and '## Facilities and labs' in docs and 'no fixed consultation duration' in docs)
for label,ok in checks: print(('PASS' if ok else 'FAIL')+' '+label)
print(f'{sum(ok for _,ok in checks)}/{len(checks)} checks passed')
raise SystemExit(0 if all(ok for _,ok in checks) else 1)
